", "const headers = (): Record<string, string> => ({
 'X-UserToken': (window as any).g_ck,
 'Accept': 'application/json',
});

const writeHeaders = (): Record<string, string> => ({
 ...headers(),
 'Content-Type': 'application/json',
});

export async function fetchCount(table: string, query = ''): Promise<number> {
 const q = query ? `&sysparm_query=${encodeURIComponent(query)}` : '';
 const res = await fetch(`/api/now/stats/${table}?sysparm_count=true${q}`, { headers: headers() });
 const data = await res.json();
 return parseInt(data.result?.stats?.count || '0', 10);
}

export async function fetchRecords(
 table: string, query = '', limit = 20, offset = 0, fields?: string
): Promise<{ records: any[]; count: number }> {
 const p = new URLSearchParams({
 sysparm_display_value: 'all',
 sysparm_limit: String(limit),
 sysparm_offset: String(offset),
 });
 if (query) p.set('sysparm_query', query);
 if (fields) p.set('sysparm_fields', fields);
 const res = await fetch(`/api/now/table/${table}?${p}`, { headers: headers() });
 const total = parseInt(res.headers.get('X-Total-Count') || '0', 10);
 const data = await res.json();
 return { records: data.result || [], count: total };
}

export async function fetchRecord(table: string, id: string): Promise<any> {
 const res = await fetch(
 `/api/now/table/${table}/${id}?sysparm_display_value=all`,
 { headers: headers() }
 );
 const data = await res.json();
 return data.result;
}

export async function createRecord(table: string, body: Record<string, string>): Promise<any> {
 const res = await fetch(`/api/now/table/${table}`, {
 method: 'POST', headers: writeHeaders(), body: JSON.stringify(body),
 });
 const data = await res.json();
 if (!res.ok) {
 throw new Error(data?.error?.message || `Server error (${res.status})`);
 }
 return data.result;
}

export async function updateRecord(table: string, id: string, body: Record<string, string>): Promise<any> {
 const res = await fetch(`/api/now/table/${table}/${id}`, {
 method: 'PATCH', headers: writeHeaders(), body: JSON.stringify(body),
 });
 const data = await res.json();
 if (!res.ok) {
 throw new Error(data?.error?.message || `Server error (${res.status})`);
 }
 return data.result;
}

export async function getCurrentUserId(): Promise<string> {
 const q = 'sysparm_query=user_name%3Djavascript%3Ags.getUserName()&sysparm_limit=1&sysparm_fields=sys_id';
 const res = await fetch(`/api/now/table/sys_user?${q}`, { headers: headers() });
 const data = await res.json();
 return data.result?.[0]?.sys_id || '';
}

export async function getCurrentUser(): Promise<{ sys_id: string; name: string; title: string }> {
 const q = 'sysparm_query=user_name%3Djavascript%3Ags.getUserName()&sysparm_limit=1&sysparm_fields=sys_id,name,title&sysparm_display_value=all';
 const res = await fetch(`/api/now/table/sys_user?${q}`, { headers: headers() });
 const data = await res.json();
 const u = data.result?.[0];
 return {
 sys_id: u?.sys_id?.value || u?.sys_id || '',
 name: u?.name?.display_value || u?.name?.value || u?.name || 'User',
 title: u?.title?.display_value || u?.title?.value || u?.title || '',
 };
}

export async function searchUsers(term: string): Promise<any[]> {
 const q = encodeURIComponent(`nameLIKE${term}^ORuser_nameLIKE${term}^ORemailLIKE${term}^active=true`);
 const p = new URLSearchParams({
 sysparm_query: `nameLIKE${term}^ORuser_nameLIKE${term}^ORemailLIKE${term}^active=true`,
 sysparm_limit: '15',
 sysparm_fields: 'sys_id,name,user_name,email,department,active',
 sysparm_display_value: 'all',
 });
 const res = await fetch(`/api/now/table/sys_user?${p}`, { headers: headers() });
 const data = await res.json();
 return data.result || [];
}

export interface PunchTime { value: string; display: string; }

export interface PunchState {
 employee: { sys_id: string; name: string; number: string };
 date: string;
 server_time_ms: number;
 tz_offset_ms: number;
 punched: boolean;
 attendance_id: string;
 status: { value: string; display: string } | null;
 check_in: PunchTime | null;
 check_out: PunchTime | null;
 last_punch: PunchTime | null;
 working_hours: string | null;
}

export class PunchError extends Error {
 code: string;
 constructor(code: string, message: string) { super(message); this.code = code; }
}

async function attendanceCall(path: string, method: 'GET' | 'POST'): Promise<PunchState> {
 let res: Response;
 try {
 res = await fetch(`/api/x_2316161_bjit_e_0/attendance/${path}`, {
 method,
 headers: method === 'POST' ? writeHeaders() : headers(),
 body: method === 'POST' ? '{}' : undefined,
 });
 } catch {
 throw new PunchError('network', 'Unable to reach the server. Please check your connection and try again.');
 }
 let data: any = null;
 try { data = await res.json(); } catch { /* handled below */ }
 if (!res.ok) {
 throw new PunchError(data?.result?.code || 'server_error', data?.result?.message || `Server error (${res.status})`);
 }
 return data.result as PunchState;
}

/** Today's attendance for the logged-in employee; the employee is resolved on the server. */
export const getTodayAttendance = () => attendanceCall('today', 'GET');

/** PUNCH NOW: the server decides whether this is the first punch (check-in) or a later one (check-out). */
export const punchNow = () => attendanceCall('punch', 'POST');

export interface EmployeeContext {
 userId: string;
 empId: string;
 empRecord: any | null;
 error: string;
}

export async function getMyEmployee(): Promise<EmployeeContext> {
 const userId = await getCurrentUserId();
 if (!userId) return { userId: '', empId: '', empRecord: null, error: 'Unable to identify your ServiceNow account.' };
 const emp = await fetchRecords('x_2316161_bjit_e_0_emp', `user=${userId}`, 1);
 if (!emp.records.length) return { userId, empId: '', empRecord: null, error: 'no_profile' };
 const rec = emp.records[0];
 const empId = rec.sys_id?.value || rec.sys_id || '';
 const status = rec.employment_status?.value || rec.employment_status || '';
 if (status === 'terminated' || status === 'resigned' || status === 'retired')
 return { userId, empId, empRecord: rec, error: 'Your employee profile is currently inactive. Please contact HR for assistance.' };
 return { userId, empId, empRecord: rec, error: '' };
}
