", "import React from 'react';
import EmptyState from './EmptyState';

export interface Column {
 key: string;
 label: string;
 render?: (val: any, row: any) => React.ReactNode;
}

interface Props {
 columns: Column[];
 data: any[];
 onRowClick?: (row: any) => void;
 page?: number;
 total?: number;
 pageSize?: number;
 onPageChange?: (page: number) => void;
}

function formatCell(val: any): string {
 if (val == null) return '—';
 if (typeof val === 'object') return val.display_value || val.value || '—';
 return String(val);
}

export default function DataTable({
 columns, data, onRowClick, page = 1, total, pageSize = 20, onPageChange,
}: Props) {
 if (!data.length) return <EmptyState message="No records found" />;

 const count = total ?? data.length;
 const totalPages = Math.ceil(count / pageSize) || 1;

 return (
 <div className="table-wrapper">
 <table className="data-table">
 <thead>
 <tr>{columns.map(c => <th key={c.key}>{c.label}</th>)}</tr>
 </thead>
 <tbody>
 {data.map((row, i) => (
 <tr key={row.sys_id?.value || i}
 onClick={() => onRowClick?.(row)}
 className={onRowClick ? 'clickable' : ''}>
 {columns.map(c => (
 <td key={c.key}>
 {c.render ? c.render(row[c.key], row) : formatCell(row[c.key])}
 </td>
 ))}
 </tr>
 ))}
 </tbody>
 </table>
 {count > pageSize && onPageChange && (
 <div className="table-pagination">
 <button disabled={page <= 1} onClick={() => onPageChange(page - 1)}>← Prev</button>
 <span>Page {page} of {totalPages}</span>
 <button disabled={page >= totalPages} onClick={() => onPageChange(page + 1)}>Next →</button>
 </div>
 )}
 </div>
 );
}
