", "import React, { useState, useEffect, useRef } from 'react';
import { searchUsers } from '../services/api';

interface Props {
 value: string;
 displayValue?: string;
 onChange: (sysId: string, display: string) => void;
}

export default function UserPicker({ value, displayValue, onChange }: Props) {
 const [query, setQuery] = useState(displayValue || '');
 const [results, setResults] = useState<any[]>([]);
 const [open, setOpen] = useState(false);
 const [selected, setSelected] = useState(!!value);
 const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
 const wrapRef = useRef<HTMLDivElement>(null);

 useEffect(() => {
 if (displayValue && value) { setQuery(displayValue); setSelected(true); }
 }, [displayValue, value]);

 useEffect(() => {
 const close = (e: MouseEvent) => {
 if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
 };
 document.addEventListener('mousedown', close);
 return () => document.removeEventListener('mousedown', close);
 }, []);

 const search = (term: string) => {
 setQuery(term);
 setSelected(false);
 onChange('', '');
 if (timer.current) clearTimeout(timer.current);
 if (term.length < 2) { setResults([]); setOpen(false); return; }
 timer.current = setTimeout(async () => {
 const r = await searchUsers(term);
 setResults(r);
 setOpen(true);
 }, 300);
 };

 const select = (user: any) => {
 const id = user.sys_id?.value || user.sys_id;
 const name = user.name?.display_value || user.name?.value || '';
 setQuery(name);
 setSelected(true);
 setOpen(false);
 onChange(id, name);
 };

 const clear = () => { setQuery(''); setSelected(false); onChange('', ''); setResults([]); };
 const dv = (f: any) => f?.display_value || f?.value || f || '';

 return (
 <div ref={wrapRef} className="user-picker">
 <div style={{ display: 'flex', gap: '8px' }}>
 <input className="form-input" placeholder="Search by name, username, or email..."
 value={query} onChange={e => search(e.target.value)}
 onFocus={() => { if (results.length && !selected) setOpen(true); }}
 readOnly={selected}
 style={selected ? { background: '#f0fdf4', borderColor: '#059669' } : {}} />
 {selected && <button type="button" className="btn btn-secondary btn-sm" onClick={clear}>✕</button>}
 </div>
 {open && (
 <div className="picker-dropdown">
 {results.length === 0 ? (
 <div className="picker-option" style={{ color: 'var(--erp-text-muted)' }}>No users found</div>
 ) : results.map(u => (
 <div key={u.sys_id?.value || u.sys_id} className="picker-option" onClick={() => select(u)}>
 <strong>{dv(u.name)}</strong>
 <span className="picker-meta">{dv(u.user_name)} · {dv(u.email)}</span>
 </div>
 ))}
 </div>
 )}
 </div>
 );
}
", "import React, { useEffect } from 'react';

interface Props {
 message: string;
 type?: 'success' | 'error' | 'info';
 onClose: () => void;
}

export default function Toast({ message, type = 'info', onClose }: Props) {
