 Promise.all([
 fetchRecord(TABLE, params.id),
 fetchRecords(T_DESGN, 'active=true^ORDERBYname', 100),
 ]).then(([r, d]) => {
 if (r) {
 const f: Record<string, string> = {};
 ['employment_type', 'employment_status', 'joining_date', 'personal_email',
 'emergency_contact', 'emergency_phone', 'date_of_birth', 'designation',
 'blood_group', 'marital_status'].forEach(k => { f[k] = val(r[k]); });
 setForm(f);
 }
 setDesignations(d.records);
 setLoading(false);
 });
