", "import React, { useEffect, useState, useCallback, useRef } from 'react';
import { fetchRecords, getTodayAttendance, punchNow, PunchError, PunchState } from '../../services/api';
import Spinner from '../../components/Spinner';
import Toast from '../../components/Toast';
import NoEmployeeProfile from '../../components/NoEmployeeProfile';
import DataTable, { Column } from '../../components/DataTable';
import StatusBadge from '../../components/StatusBadge';
import PunchCard from './PunchCard';
import { dv } from '../../utils/format';

const T_ATT = 'x_2316161_bjit_e_0_attend';
const NOT_RECORDED = 'Not recorded';

function workedLabel(state: PunchState | null): string {
 if (!state?.check_out || !state.working_hours) return '—';
 const totalMinutes = Math.round(parseFloat(state.working_hours) * 60);
 if (isNaN(totalMinutes)) return '—';
 return `${Math.floor(totalMinutes / 60)}h ${String(totalMinutes % 60).padStart(2, '0')}m`;
}

export default function MyAttendance(_props: { params: Record<string, string> }) {
 const [state, setState] = useState<PunchState | null>(null);
 const [clockOffsetMs, setClockOffsetMs] = useState(0);
 const [history, setHistory] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [loadError, setLoadError] = useState<PunchError | null>(null);
 const [punching, setPunching] = useState(false);
 const inFlight = useRef(false);
 const [toast, setToast] = useState({ msg: '', type: 'success' as 'success' | 'error' | 'info' });
 const closeToast = useCallback(() => setToast({ msg: '', type: 'info' }), []);

 const applyState = useCallback((s: PunchState) => {
 setState(s);
 setClockOffsetMs(s.server_time_ms - Date.now() + s.tz_offset_ms);
 }, []);

 const loadHistory = useCallback(async (empId: string) => {
 const res = await fetchRecords(T_ATT, `employee=${empId}^ORDERBYDESCdate`, 20);
 setHistory(res.records);
 }, []);

 useEffect(() => {
 (async () => {
 try {
 const s = await getTodayAttendance();
 applyState(s);
 await loadHistory(s.employee.sys_id).catch(() => undefined);
 } catch (err) {
 setLoadError(err instanceof PunchError ? err : new PunchError('server_error', 'Unable to load attendance.'));
 }
 setLoading(false);
 })();
 }, [applyState, loadHistory]);

 const handlePunch = async () => {
 if (inFlight.current) return;
 inFlight.current = true;
 setPunching(true);
 const wasFirst = !state?.check_in;
 try {
 const s = await punchNow();
 applyState(s);
 setToast({
 msg: wasFirst ? `Punch recorded — checked in at ${s.check_in?.display}` : `Punch recorded — latest punch at ${s.last_punch?.display}`,
 type: 'success',
 });
 await loadHistory(s.employee.sys_id).catch(() => undefined);
 } catch (err: any) {
 setToast({ msg: err.message || 'Punch failed. Please try again.', type: 'error' });
 }
 inFlight.current = false;
 setPunching(false);
 };

 if (loading) return <Spinner />;
 if (loadError?.code === 'no_employee_profile') return <NoEmployeeProfile />;
 if (loadError) return <NoEmployeeProfile message={loadError.message} />;
 if (!state) return null;

 const attCols: Column[] = [
 { key: 'date', label: 'Date', render: v => dv(v) },
 { key: 'check_in', label: 'In', render: v => dv(v) },
 { key: 'check_out', label: 'Out', render: v => dv(v) },
 { key: 'working_hours', label: 'Hours', render: v => dv(v) },
 { key: 'status', label: 'Status', render: v => <StatusBadge status={v} /> },
 ];

 return (
 <div>
 {toast.msg && <Toast message={toast.msg} type={toast.type} onClose={closeToast} />}
 <PunchCard
 empName={state.employee.name} empNumber={state.employee.number} clockOffsetMs={clockOffsetMs}
 statusLabel={state.status?.display || 'Not punched yet'}
 checkIn={state.check_in?.display || NOT_RECORDED} checkOut={state.check_out?.display || NOT_RECORDED}
 lastPunch={state.last_punch?.display || NOT_RECORDED} workedLabel={workedLabel(state)}
 punching={punching} onPunch={handlePunch} />
 <h3 style={{ margin: '24px 0 12px' }}>Attendance History</h3>
 <DataTable columns={attCols} data={history} total={history.length} />
 </div>
 );
}
