", "import React, { useEffect, useState } from 'react';

interface Props {
 empName: string;
 empNumber: string;
 /** Server time minus browser time, plus the attendance timezone offset (ms). */
 clockOffsetMs: number;
 statusLabel: string;
 checkIn: string;
 checkOut: string;
 lastPunch: string;
 workedLabel: string;
 punching: boolean;
 onPunch: () => void;
}

const DAY_LABEL: Intl.DateTimeFormatOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' };

// Shifting by the server's offset and reading UTC fields shows attendance-timezone time, not the browser's.
function ServerClock({ offsetMs }: { offsetMs: number }) {
 const [now, setNow] = useState(() => new Date(Date.now() + offsetMs));
 useEffect(() => {
 const tick = () => setNow(new Date(Date.now() + offsetMs));
 tick();
 const iv = setInterval(tick, 1000);
 return () => clearInterval(iv);
 }, [offsetMs]);
 return (
 <>
 <div className="punch-date">{now.toLocaleDateString('en-US', DAY_LABEL)}</div>
 <div className="punch-clock">{now.toISOString().substring(11, 19)}</div>
 </>
 );
}

export default function PunchCard({
 empName, empNumber, clockOffsetMs, statusLabel, checkIn, checkOut, lastPunch, workedLabel, punching, onPunch,
}: Props) {
 return (
 <div className="punch-card">
 <div style={{ fontWeight: 600, fontSize: 16 }}>{empName} <span style={{ color: 'var(--erp-text-muted)', fontWeight: 400, fontSize: 13 }}>({empNumber})</span></div>
 <ServerClock offsetMs={clockOffsetMs} />
 <div className="punch-status">
 <div className="punch-stat"><span className="punch-stat-label">Status</span><span className="punch-stat-value">{statusLabel}</span></div>
 <div className="punch-stat"><span className="punch-stat-label">Check-in</span><span className="punch-stat-value">{checkIn}</span></div>
 <div className="punch-stat"><span className="punch-stat-label">Check-out</span><span className="punch-stat-value">{checkOut}</span></div>
 <div className="punch-stat"><span className="punch-stat-label">Last punch</span><span className="punch-stat-value">{lastPunch}</span></div>
 <div className="punch-stat"><span className="punch-stat-label">Worked</span><span className="punch-stat-value">{workedLabel}</span></div>
 </div>
 <button className="punch-btn punch-btn-now" disabled={punching} aria-busy={punching} onClick={onPunch}>
 {punching ? 'Saving…' : '🕐 PUNCH NOW'}
 </button>
 </div>
 );
}
