const T = 'x_2316161_bjit_e_0_lv_app';

export default function LeaveOverview(_props: { params: Record<string, string> }) {
 const [stats, setStats] = useState<Record<string, number>>({});
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 Promise.all([
 fetchCount(T, 'status=pending'),
 fetchCount(T, 'status=mgr_approved'),
 fetchCount(T, 'status=approved'),
 fetchCount(T, 'status=rejected'),
 ]).then(([pending, mgrApproved, approved, rejected]) => {
 setStats({ pending, mgrApproved, approved, rejected });
 setLoading(false);
 });
 }, []);

 if (loading) return <Spinner />;

 return (
 <div>
 <div className="kpi-grid">
 <KpiCard title="Pending" value={stats.pending} icon="⏳" color="var(--erp-warning)" />
 <KpiCard title="Manager Approved" value={stats.mgrApproved} icon="👤" color="var(--erp-accent)" />
 <KpiCard title="Approved" value={stats.approved} icon="✅" color="var(--erp-success)" />
 <KpiCard title="Rejected" value={stats.rejected} icon="❌" color="var(--erp-danger)" />
 </div>
 <div className="quick-actions">
 <h3>Leave Actions</h3>
 <div className="action-grid">
 <button className="action-btn" onClick={() => navigate('leave-apply')}>✈️ Apply for Leave</button>
 <button className="action-btn" onClick={() => navigate('my-leaves')}>📄 My Leaves</button>
 <button className="action-btn" onClick={() => navigate('leave-approvals')}>✅ Pending Approvals</button>
 </div>
 </div>
 </div>
 );
}
", "import React, { useEffect, useState } from 'react';
import { fetchRecords, createRecord, getMyEmployee } from '../../services/api';
import PageHeader from '../../components/PageHeader';
import FormField from '../../components/FormField';
import Toast from '../../components/Toast';
import Spinner from '../../components/Spinner';
import NoEmployeeProfile from '../../components/NoEmployeeProfile';
import { navigate } from '../../utils/router';
import { val } from '../../utils/format';

const T_LT = 'x_2316161_bjit_e_0_lv_type';
const T_LA = 'x_2316161_bjit_e_0_lv_app';

export default function LeaveApply(_props: { params: Record<string, string> }) {
 const [empId, setEmpId] = useState('');
 const [types, setTypes] = useState<any[]>([]);
 const [form, setForm] = useState<Record<string, string>>({});
 const [saving, setSaving] = useState(false);
 const [toast, setToast] = useState('');
 const [ready, setReady] = useState(false);
 const [noProfile, setNoProfile] = useState('');

 useEffect(() => {
 (async () => {
 const ctx = await getMyEmployee();
 if (ctx.error || !ctx.empId) { setNoProfile(ctx.error || 'no_profile'); setReady(true); return; }
 setEmpId(ctx.empId);
 const lt = await fetchRecords(T_LT, 'active=true', 50);
 setTypes(lt.records);
 setReady(true);
 })();
 }, []);

 const set = (k: string, v: string) => setForm(p => ({ ...p, [k]: v }));

 const duration = () => {
 if (!form.start_date || !form.end_date) return 0;
 const d = (new Date(form.end_date).getTime() - new Date(form.start_date).getTime()) / 86400000 + 1;
 return d > 0 ? d : 0;
 };

 const submit = async (e: React.FormEvent) => {
 e.preventDefault();
 if (!form.leave_type || !form.start_date || !form.end_date || !form.reason) {
 setToast('Please fill all required fields.'); return;
 }
 if (duration() <= 0) { setToast('End date must be on or after start date.'); return; }
 setSaving(true);
 try {
 const rec = await createRecord(T_LA, {
 employee: empId, leave_type: form.leave_type,
 start_date: form.start_date, end_date: form.end_date,
 reason: form.reason, status: 'pending',
 });
 navigate('leave-detail', { id: val(rec.sys_id) || rec.sys_id });
 } catch (err: any) { setToast(err.message || 'Failed to submit leave application.'); }
 setSaving(false);
 };

 if (!ready) return <Spinner />;
 if (noProfile) return <NoEmployeeProfile message={noProfile === 'no_profile' ? undefined : noProfile} />;

 return (
 <div>
 <PageHeader title="Apply for Leave" />
 {toast && <Toast message={toast} type="error" onClose={() => setToast('')} />}
 <form className="form-card" onSubmit={submit}>
 <div className="form-grid">
 <FormField label="Leave Type" required>
 <select className="form-input" value={form.leave_type || ''} onChange={e => set('leave_type', e.target.value)}>
 <option value="">Select leave type</option>
 {types.map(t => (
 <option key={val(t.sys_id)} value={val(t.sys_id)}>
 {t.name?.display_value || t.name?.value || val(t.name)}
 </option>
 ))}
 </select>
 </FormField>
 <FormField label="Start Date" required>
 <input className="form-input" type="date" value={form.start_date || ''} onChange={e => set('start_date', e.target.value)} />
 </FormField>
 <FormField label="End Date" required>
 <input className="form-input" type="date" value={form.end_date || ''} onChange={e => set('end_date', e.target.value)} />
 </FormField>
 <FormField label="Duration">
 <input className="form-input" readOnly value={`${duration()} day(s)`} />
 </FormField>
 </div>
 <FormField label="Reason" required>
 <textarea className="form-input form-textarea" value={form.reason || ''} onChange={e => set('reason', e.target.value)} />
 </FormField>
 <div className="form-actions">
 <button type="button" className="btn btn-secondary" onClick={() => navigate('leave')}>Cancel</button>
 <button type="submit" className="btn btn-primary" disabled={saving}>
 {saving ? 'Submitting...' : 'Submit Application'}
 </button>
 </div>
 </form>
 </div>
 );
}
", "import React, { useEffect, useState } from 'react';
import { fetchRecords, getMyEmployee } from '../../services/api';
import DataTable, { Column } from '../../components/DataTable';
import StatusBadge from '../../components/StatusBadge';
import Spinner from '../../components/Spinner';
import PageHeader from '../../components/PageHeader';
import NoEmployeeProfile from '../../components/NoEmployeeProfile';
import { navigate } from '../../utils/router';
import { dv, val } from '../../utils/format';

const T_LV = 'x_2316161_bjit_e_0_lv_app';

const columns: Column[] = [
 { key: 'number', label: 'ID', render: v => dv(v) },
 { key: 'leave_type', label: 'Type', render: v => dv(v) },
 { key: 'start_date', label: 'From', render: v => dv(v) },
 { key: 'end_date', label: 'To', render: v => dv(v) },
 { key: 'duration', label: 'Days', render: v => dv(v) },
 { key: 'status', label: 'Status', render: v => <StatusBadge status={v} /> },
];

export default function MyLeaves(_props: { params: Record<string, string> }) {
 const [data, setData] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [noProfile, setNoProfile] = useState('');

 useEffect(() => {
 (async () => {
 const ctx = await getMyEmployee();
 if (ctx.error || !ctx.empId) { setNoProfile(ctx.error || 'no_profile'); setLoading(false); return; }
 const r = await fetchRecords(T_LV, `employee=${ctx.empId}^ORDERBYDESCsys_created_on`, 50);
 setData(r.records);
 setLoading(false);
 })();
 }, []);

 if (loading) return <Spinner />;
 if (noProfile) return <NoEmployeeProfile message={noProfile === 'no_profile' ? undefined : noProfile} />;

 return (
 <div>
 <PageHeader title="My Leave Requests" actions={
 <button className="btn btn-primary" onClick={() => navigate('leave-apply')}>+ Apply Leave</button>
 } />
 <DataTable columns={columns} data={data} total={data.length}
 onRowClick={row => navigate('leave-detail', { id: val(row.sys_id) })} />
 </div>
 );
}
