 <div className="detail-item"><label>Leave Type</label><span>{dv(rec.leave_type)}</span></div>
 <div className="detail-item"><label>Start Date</label><span>{dv(rec.start_date)}</span></div>
 <div className="detail-item"><label>End Date</label><span>{dv(rec.end_date)}</span></div>
