 );
}
", "import React, { useEffect, useState } from 'react';
import { fetchRecords, updateRecord } from '../../services/api';
import DataTable, { Column } from '../../components/DataTable';
import Spinner from '../../components/Spinner';
import PageHeader from '../../components/PageHeader';
import Toast from '../../components/Toast';
import { dv, val } from '../../utils/format';

const TABLE = 'x_2316161_bjit_e_0_lv_app';

export default function LeaveApprovals(_props: { params: Record<string, string> }) {
 const [data, setData] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [toast, setToast] = useState({ msg: '', type: 'info' as 'success' | 'error' | 'info' });

 const load = () => {
 setLoading(true);
 fetchRecords(TABLE, 'status=pending^ORDERBYDESCsys_created_on', 50).then(r => {
 setData(r.records); setLoading(false);
 });
 };

 useEffect(() => { load(); }, []);

 const handleAction = async (id: string, status: string) => {
 try {
 await updateRecord(TABLE, id, { status });
 setToast({ msg: `Leave ${status}`, type: 'success' });
 load();
 } catch { setToast({ msg: 'Action failed', type: 'error' }); }
 };

 const columns: Column[] = [
 { key: 'number', label: 'ID', render: v => dv(v) },
 { key: 'employee', label: 'Employee', render: v => dv(v) },
 { key: 'leave_type', label: 'Type', render: v => dv(v) },
 { key: 'start_date', label: 'From', render: v => dv(v) },
 { key: 'end_date', label: 'To', render: v => dv(v) },
 { key: 'duration', label: 'Days', render: v => dv(v) },
 {
 key: 'sys_id', label: 'Actions',
 render: (_v, row) => (
 <div className="table-actions">
 <button className="btn btn-sm btn-success"
 onClick={e => { e.stopPropagation(); handleAction(val(row.sys_id), 'approved'); }}>
 Approve
 </button>
 <button className="btn btn-sm btn-danger"
 onClick={e => { e.stopPropagation(); handleAction(val(row.sys_id), 'rejected'); }}>
 Reject
 </button>
 </div>
 ),
 },
 ];

 return (
 <div>
 <PageHeader title="Pending Approvals" />
 {toast.msg && <Toast message={toast.msg} type={toast.type}
 onClose={() => setToast({ msg: '', type: 'info' })} />}
 {loading ? <Spinner /> : <DataTable columns={columns} data={data} total={data.length} />}
 </div>
 );
}
